const contributorState=item=>item.status==='unavailable'?'計算不能':item.active?'高反応':'低反応';
const motionLabel=value=>({applying:'接近中',separating:'離反中',stationary:'変化僅少',unknown:'判定不能'}[value]||'判定不能');
const calculationQualityLabel=value=>({complete:'完全',partial:'一部不足',unavailable:'計算不能'}[value]||'未指定');
const ephemerisLabel=metadata=>metadata.ephemerisId==='astronomy-engine'?'Astronomy Engine':metadata.ephemerisPrecision==='fallback'?'内蔵近似計算':'天文計算エンジン';
const precisionLabel=value=>({high:'高精度',fallback:'近似',unspecified:'未指定'}[value]||'検証用');
