const contributorDetails=item=>(item.details||[]).map(detail=>{
  if(detail.bodies)return`${detail.bodies.join('―')} ${detail.aspectAngle}°／離角 ${detail.separation.toFixed(2)}°／オーブ ${detail.orb.toFixed(2)}°／${motionLabel(detail.motion)}`;
  if(detail.body)return`${detail.body}―${detail.angle}／オーブ ${detail.orb.toFixed(2)}°／${motionLabel(detail.motion)}`;
  return`${detail.phase}側／離角 ${detail.separation.toFixed(2)}°／オーブ ${detail.orb.toFixed(2)}°／${motionLabel(detail.motion)}`;
}).map(text=>`<small>${esc(text)}</small>`).join('');

